export const NO_FILTER = Object.freeze({ place: "", type: "", subtype: "" });

/* The nine types the grid offers, in its order, and the registry kinds each
 * holds. Every kind the registry allows (scraper/festivals/registry.py's
 * KINDS) belongs to exactly one. */
export const TYPES = Object.freeze([
  { id: "music", kinds: ["music"] },
  { id: "film", kinds: ["film"] },
  { id: "theatre", kinds: ["theatre"] },
  { id: "dance", kinds: ["dance"] },
  { id: "comedy", kinds: ["comedy"] },
  { id: "art", kinds: ["art", "literature"] },
  { id: "mixed", kinds: ["fringe", "multi"] },
  { id: "sports", kinds: ["sports"] },
  { id: "academic", kinds: ["academic"] },
]);

/** The type a registry kind belongs to, or null for a kind no type holds. */
export function typeOfKind(kind) {
  const type = TYPES.find((t) => t.kinds.includes(kind));
  return type ? type.id : null;
}

/** A place filter's value for a festival's city. */
export function cityPlace(festival) {
  return `${festival.country}/${festival.city}`;
}
  border-inline-start: 0;
  padding-inline-start: 0;
}
/* The festivals' rows scroll inside a strip that keeps its height, however
   many the year draws; the trip's band, its ends and the travel pictures stay
   put over them. The scrollbar is left out so the rows keep the months' exact
   width, and a fade at an edge says more rows lie past it. */
.tl-track {
  position: relative;
}
.tl-rows {
  position: relative;
  min-height: 64px;
  max-height: calc(7.5 * 30px + 6px);
  overflow-y: auto;
  scrollbar-width: none;
}
.tl-rows::-webkit-scrollbar {
  display: none;
}
.tl-rows.is-more-below {
  mask-image: linear-gradient(to bottom, #000 calc(100% - 30px), transparent);
}
.tl-rows.is-more-above {
  mask-image: linear-gradient(to top, #000 calc(100% - 30px), transparent);
}
.tl-rows.is-more-above.is-more-below {
  mask-image: linear-gradient(transparent, #000 30px, #000 calc(100% - 30px), transparent);
}
.tl-period {
  position: absolute;
  top: -8px;
  bottom: 0;
  background: color-mix(in srgb, var(--violet) 14%, transparent);
  border-radius: 4px;
}
/* Today: a stick figure standing on the months' line, holding up a sign. It
   shifts about a little, and cheers when the reader makes a choice. */
.tl-today {
  position: absolute;
  bottom: -1px;
  width: 0;
  height: 0;
  color: var(--ink);
  z-index: 3;
  pointer-events: none;
}
.tl-dude {
  position: absolute;
  bottom: 0;
  left: -10px;
  overflow: visible;
}
.tl-sign {
  position: absolute;
  bottom: 33px;
  left: 6px;
  transform: translateX(-50%);
  transform-origin: 50% calc(100% + 10px);
  padding: 0 4px;
  border: 1.5px solid var(--ink);
  border-radius: 3px;
  background: var(--paper);
  font-size: 0.6rem;
  font-weight: 800;
  line-height: 12px;
  white-space: nowrap;
  animation: tl-sign-sway 3.2s ease-in-out infinite;
}
.tl-sign::after {
  content: "";
  position: absolute;
  top: 100%;
  left: 50%;
  width: 1.5px;
  height: 10px;
  margin-left: -0.75px;
  background: var(--ink);
}
.tl-dude .dude-arm {
  transform-box: view-box;
  transform-origin: 10px 12px;
  animation: tl-arm-swing 2.4s ease-in-out infinite;
}
.tl-dude .dude-leg {
  transform-box: view-box;
  transform-origin: 10px 21px;
  animation: tl-leg-tap 1.9s ease-in-out infinite;
}
.tl-today.is-cheering .tl-dude,
.tl-today.is-cheering .tl-sign {
  animation: tl-cheer 0.55s ease-out 2;
}
.tl-today.is-cheering .dude-arm {
  animation: tl-arm-cheer 1.1s ease-out 1;
}
@keyframes tl-sign-sway {
  0%, 100% { transform: translateX(-50%) rotate(-4deg); }
  50% { transform: translateX(-50%) rotate(4deg); }
}
@keyframes tl-arm-swing {
  0%, 100% { transform: rotate(-10deg); }
  50% { transform: rotate(12deg); }
}
@keyframes tl-leg-tap {
  0%, 70%, 100% { transform: rotate(0deg); }
  80% { transform: rotate(-8deg); }
}
@keyframes tl-cheer {
  0%, 100% { translate: 0 0; }
  40% { translate: 0 -5px; }
}
@keyframes tl-arm-cheer {
  0%, 100% { transform: rotate(0deg); }
  20%, 80% { transform: rotate(125deg); }
}
@media (prefers-reduced-motion: reduce) {
  .tl-sign,
  .tl-dude .dude-arm,
  .tl-dude .dude-leg,
  .tl-today.is-cheering .tl-dude,
  .tl-today.is-cheering .tl-sign,
  .tl-today.is-cheering .dude-arm {
    animation: none;
  }
}
.tl-item {
  position: absolute;
  display: flex;
  align-items: center;
  gap: 6px;
  height: 26px;
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
  color: var(--ink);
  white-space: nowrap;
}
.tl-item--late {
  flex-direction: row-reverse;
}
.tl-bar {
  flex: 0 0 auto;
  height: 12px;
  border-radius: 6px;
  background: var(--muted);
}
.tl-item.is-empty .tl-bar {
  background: transparent;
  border: 2px solid var(--muted);
}
.tl-label {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--muted);
}
.tl-item:hover .tl-label,
.tl-item:focus-visible .tl-label {
  color: var(--ink);
}
.tl-item.is-focus .tl-bar {
  background: var(--violet);
  border-color: var(--violet);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--violet) 28%, transparent);
}
.tl-item.is-focus .tl-label {
  color: var(--violet-dark);
  font-weight: 800;
}
/* A city's pill: its flag at the middle, and inside a pill of several
   festivals each one's run as a shade of its own, darkest where most of them
   run at once. */
.tl-bar {
  position: relative;
}
.tl-item--bunch .tl-bar {
  height: 14px;
  border-radius: 7px;
  background: color-mix(in srgb, var(--muted) 35%, transparent);
  overflow: hidden;
}
.tl-run {
  position: absolute;
  top: 0;
  bottom: 0;
  background: color-mix(in srgb, var(--muted) 45%, transparent);
}
.tl-item--bunch.is-focus .tl-bar {
  background: color-mix(in srgb, var(--violet) 35%, transparent);
}
.tl-item--bunch.is-focus .tl-run {
  background: color-mix(in srgb, var(--violet) 45%, transparent);
}
.tl-flag {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 18px;
  height: 12px;
  transform: translate(-50%, -50%);
  border-radius: 2px;
  box-shadow: 0 0 0 1.5px var(--paper), 0 1px 3px color-mix(in srgb, var(--ink) 35%, transparent);
}
.tl-card-name {
  font-weight: 700;
}
.tl-none {
  margin: 4px 0;
  font-size: 0.85rem;
  color: var(--muted);
}

/* --- the trip: its band on the year, its dates, the flights either side ---- */

/* Each end of the trip's band is a handle: a line across the whole strip,
   months and all, with a grip at its middle to take hold of. */
.tl-handle {
  position: absolute;
  top: -26px;
  bottom: 0;
  /* Narrow, so a short trip's band still has room to be taken hold of
     between its two ends; the grip is wider than the line it sits on. */
  width: 10px;
  margin-inline-start: -5px;
  touch-action: none;
  z-index: 2;
}
.tl-handle::before {
  content: "";
  position: absolute;
