.timeline {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  grid-template-areas: "place main types";
  column-gap: 14px;
  align-items: start;
}
.tl-filters {
  display: contents;
}
.tl-main {
  grid-area: main;
  min-width: 0;
}
/* One family of capsules speaks for every choice on the bar: the globe's
   badges and its way back out, the chosen type's subtypes, and the trip's
   length on the year. A chosen one fills with the page's colour. */
.tl-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 20px;
  padding: 0 8px;
  border: 1.5px solid color-mix(in srgb, var(--violet) 45%, var(--line));
  border-radius: 999px;
  background: var(--paper);
  box-shadow: 0 1px 3px color-mix(in srgb, var(--ink) 22%, transparent);
  font: inherit;
  font-size: 0.66rem;
  font-weight: 800;
  line-height: 1;
  color: var(--violet-dark);
  white-space: nowrap;
}
button.tl-chip {
  cursor: pointer;
}
button.tl-chip:hover,
button.tl-chip:focus-visible {
  border-color: var(--violet);
}
button.tl-chip:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--violet) 40%, transparent);
  outline-offset: 1px;
}
.tl-chip.is-picked,
.tl-chip[aria-checked="true"] {
  border-color: var(--violet);
  background: var(--violet);
  color: var(--paper);
}

.tl-place {
  grid-area: place;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  width: 164px;
  margin-top: -22px;
}
/* The globe: a round lens onto a cut-paper earth. Its colours are read by the
   canvas through a probe placed here. */
.tl-lens {
  position: relative;
