/* The types: nine pictured tiles; once one is chosen it becomes the header,
   the other eight a row beneath it, and its subtypes chips under them. */
.tl-types {
  grid-area: types;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 212px;
  margin-top: -22px;
}
.tl-type-grid {
  display: grid;
  grid-template-columns: repeat(3, 68px);
  gap: 4px;
}
.tl-type {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  min-width: 0;
  padding: 3px 0 2px;
  border: 2px solid transparent;
  border-radius: 14px;
  background: none;
  color: var(--ink);
  font: inherit;
  cursor: pointer;
}
.tl-type img {
  display: block;
  width: 46px;
  height: 46px;
  border-radius: 12px;
  box-shadow: 0 2px 6px rgba(16, 24, 40, 0.18);
