.tl-type[aria-pressed="true"] .tl-type-name {
  max-width: none;
  font-size: 0.9rem;
  font-weight: 800;
}
.tl-type[aria-pressed="true"] .tl-type-count {
  position: static;
  margin-inline-start: auto;
