// The one reference instant every requirements case renders at, and the fixed
// fake inputs that surround it. Fixture data is authored relative to this
// moment; goldens are only comparable because nothing ever reads another clock.
//
// Saturday 15 August 2026, 19:30 in Edinburgh (BST = UTC+1): mid-festival, a
// busy evening, with shows still to start tonight and the fringe day (06:00 →
// 06:00) far from rolling over.
"use strict";

const REFERENCE_NOW_LOCAL = "2026-08-15T19:30";
const REFERENCE_NOW_UTC_MS = Date.UTC(2026, 7, 15, 18, 30, 0);

// The app adopts the device clock (our fixed time) only when geolocation
// reports an in-UK position — so the fake location is central Edinburgh,
// exactly the app's own USER_DEFAULT, which also keeps the debug pill hidden.
const GEOLOCATION = { latitude: 55.9523946827963, longitude: -3.188258484671504 };

const TIMEZONE = "Europe/London";
const LOCALE = "en-GB";

// The fringe date REFERENCE_NOW falls on (19:30 is inside the 06:00–06:00 day).
const REFERENCE_FRINGE_DATE = "2026-08-15";

// The app's own built-in simulated "now" (js/app.js), in force whenever
// geolocation does NOT confirm an in-UK position — the state the
// geolocation-denied case renders in.
const PRESET_FRINGE_DATE = "2026-08-14";

module.exports = {
  REFERENCE_NOW_LOCAL,
"use strict";
const { jerusalemReady, routeCrowdedYear } = require("../../shared/case-helpers");

/* Where the grips and the travel pictures sit, as distances from the middle of
 * the strip's visible rows, before and after scrolling those rows. */
const place = (page) =>
  page.evaluate(() => {
    const rows = document.querySelector(".tl-rows").getBoundingClientRect();
    const mid = rows.top + rows.height / 2;
    const off = (sel) => {
      const r = document.querySelector(sel).getBoundingClientRect();
      return Math.round(r.top + r.height / 2 - mid);
    };
    return {
      grips: [off(".tl-handle--from .tl-grip"), off(".tl-handle--to .tl-grip")],
      ways: [off(".tl-way--from"), off(".tl-way--to")],
    };
  });

module.exports = {
  description: "the travel pictures and the trip's grips sit at the middle of the strip's visible height, and stay there while the festivals scroll",
  page: "/planNG/?festival=jerusalem-comedy",
  viewport: "desktop",
  async verify(page, { origin, assert }) {
    await routeCrowdedYear(page);
    await page.goto(`${origin}/planNG/?festival=jerusalem-comedy`, { waitUntil: "load" });
    await jerusalemReady(page);
    const expected = { grips: [0, 0], ways: [0, 0] };
    assert.deepEqual(await place(page), expected, "centred on the visible rows");

    const scrolled = await page.evaluate(() => {
      const rows = document.querySelector(".tl-rows");
      rows.scrollTop = rows.scrollHeight;
      return rows.scrollTop;
    });
    assert.ok(scrolled > 0, "the rows scroll");
    assert.deepEqual(await place(page), expected, "and stay centred once scrolled");

    // A travel picture overlays the festivals beside the trip rather than
    // sitting in a lane beneath them.
    const over = await page.evaluate(() => {
      const way = document.querySelector(".tl-way--to").getBoundingClientRect();
      const rows = document.querySelector(".tl-rows").getBoundingClientRect();
      return way.top > rows.top && way.bottom < rows.bottom;
    });
    assert.ok(over, "inside the rows' height");
  },
};
